window.ICA_CONTENT["radical-7"] = {"origin":{"status":"source_verified_clinical_review_pending","reviewed":"2026-10-06","entity":"device","unverified":0,"audited":66},"langs":["tr","en","es"],"gaps":[{"tr":"ORi bu kayıtta hakemli bir derlemeden doğrulandı; okunan Radical-7 ABD kullanım kılavuzu (LAB-5475L) ORi'yi içermez. ORi'nin ülkedeki onay durumu ve cihaz/sensör uyumluluğu yerel olarak doğrulanmalıdır.","en":"ORi was verified from a peer-reviewed review in this record; the Radical-7 US operator's manual read (LAB-5475L) does not include ORi. Local regulatory status and device/sensor compatibility of ORi must be verified.","es":"En este registro el ORi se verificó en una revisión revisada por pares; el manual del operador estadounidense de Radical-7 consultado (LAB-5475L) no incluye el ORi. Deben verificarse localmente su estado regulatorio y la compatibilidad equipo/sensor."},{"tr":"Sensör tipine özgü yerleşim, cilt kontrol aralığı ve varsayılan alarm limitleri bu kayıtta yoktur; ilgili sensörün kullanım talimatına ve cihaz IFU'suna bakılmalıdır.","en":"Sensor-type-specific placement, skin check intervals and default alarm limits are not included in this record; refer to the sensor directions for use and the device IFU.","es":"Este registro no incluye la colocación específica por tipo de sensor, los intervalos de revisión de la piel ni los límites de alarma predeterminados; consulte las instrucciones del sensor y las IFU del equipo."},{"tr":"Klinik editör onayı, görsel yeniden yayın hakkı ve kesin 3B geometri ayrıca doğrulanmalıdır.","en":"Clinical editor approval, image republication rights and exact 3D geometry require separate verification.","es":"La aprobación del editor clínico, los derechos para volver a publicar las imágenes y la geometría 3D exacta requieren una verificación independiente."}],"animation":{"ready":false,"reason":{"tr":"Model ile sensörün tam uyumu ve tüm anatomik referanslar klinik editör tarafından henüz doğrulanmadı. Temsilî SVG koordinatları anatomik koordinatları göstermez.","en":"Exact model/sensor matching and all anatomical references have not been verified by the clinical editor. Representative SVG coordinates are not anatomical coordinates.","es":"La compatibilidad exacta entre el modelo y el sensor, así como todas las referencias anatómicas, aún no ha sido verificada por un editor clínico. Las coordenadas SVG representativas no son coordenadas anatómicas."},"scope":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"}},"sections":{"overview":{"tr":"Radical-7, uyumlu optik sensörle nabızla değişen (pulsatif) ışık absorbsiyonunu ölçen bir pulse CO-oksimetredir; rainbow çok dalga boylu sensörle SpO₂ ve nabza ek olarak SpHb, SpCO, SpMet gibi isteğe bağlı ölçümler sunabilir. El tipi veya bağımsız monitör olarak ya da Root'a yuvalanarak kullanılabilir. [5]\n\nKullanım alanları: erişkin, pediatrik ve yenidoğan hastalarda hareketli ve hareketsiz koşullarda, iyi veya kötü perfüze hastalarda SpO₂ ve nabzın sürekli noninvaziv izlenmesi; hastane, hastane benzeri kuruluşlar, mobil ve ev ortamları. [5]","en":"Radical-7 is a pulse CO-oximeter that measures pulsatile light absorption with a compatible optical sensor; with a rainbow multi-wavelength sensor it can provide optional measurements such as SpHb, SpCO and SpMet in addition to SpO₂ and pulse rate. It can be used as a handheld or standalone monitor or docked to Root. [5]\n\nApplications: continuous non-invasive monitoring of SpO₂ and pulse rate in adult, paediatric and neonatal patients under motion and no-motion conditions, in well or poorly perfused patients, in hospitals, hospital-type facilities, mobile and home environments. [5]","es":"Radical-7 es un pulsicooxímetro que mide la absorción pulsátil de la luz con un sensor óptico compatible; con un sensor multionda rainbow puede ofrecer mediciones opcionales como SpHb, SpCO y SpMet además de SpO₂ y frecuencia de pulso. Puede usarse como monitor portátil o independiente, o acoplado a Root. [5]\n\nAplicaciones: monitorización continua no invasiva de SpO₂ y frecuencia de pulso en pacientes adultos, pediátricos y neonatales, con y sin movimiento, bien o mal perfundidos, en hospitales, centros de tipo hospitalario, entornos móviles y domicilio. [5]"},"principle":{"tr":"Oksihemoglobin ve deoksihemoglobin kırmızı ve kızılötesi ışığı farklı absorbe eder (spektrofotometri); dokudaki arteriyel kan miktarı nabızla değiştiği için absorbe edilen ışık da değişir (fotopletismografi). [5] rainbow teknolojisinde çok dalga boylu sensördeki LED'ler (500–1400 nm) kapiller yataktan geçerek dedektöre ulaşır; SpCO, SpMet ve SpHb çok dalga boylu kalibrasyon denklemine dayanır. [5] Masimo SET, hareket sırasında venöz kan hareketinden kaynaklanan gürültüyü uyarlamalı filtrelerle ayırmayı amaçlar. [5]\n\nKalibrasyonun modele özgü yöntemi: SpO₂, normal COHb ve MetHb düzeyine sahip sağlıklı erişkin gönüllülerde ampirik olarak kalibre edilmiştir; doğruluk fonksiyon test cihazıyla değerlendirilemez. [5]\n\nSpHb, SpCO, SpMet gibi özellikler isteğe bağlıdır; rainbow çok dalga boylu sensör ve cihaz yapılandırmasına bağlıdır. [5]","en":"Oxyhaemoglobin and deoxyhaemoglobin absorb red and infrared light differently (spectrophotometry); because the amount of arterial blood in tissue changes with the pulse, the amount of absorbed light also changes (photoplethysmography). [5] With rainbow technology, the LEDs of the multi-wavelength sensor (500–1400 nm) pass light through a capillary bed to a detector; SpCO, SpMet and SpHb rely on a multi-wavelength calibration equation. [5] Masimo SET aims to separate noise caused by venous blood movement during motion using adaptive filters. [5]\n\nModel-specific calibration: SpO₂ is empirically calibrated in healthy adult volunteers with normal COHb and MetHb levels; a functional tester cannot be used to assess accuracy. [5]\n\nFeatures such as SpHb, SpCO and SpMet are optional and depend on the rainbow multi-wavelength sensor and device configuration. [5]","es":"La oxihemoglobina y la desoxihemoglobina absorben de forma distinta la luz roja e infrarroja (espectrofotometría); como la cantidad de sangre arterial en el tejido varía con el pulso, también varía la luz absorbida (fotopletismografía). [5] Con la tecnología rainbow, los LED del sensor multionda (500–1400 nm) atraviesan un lecho capilar hasta un detector; SpCO, SpMet y SpHb se basan en una ecuación de calibración multionda. [5] Masimo SET pretende separar con filtros adaptativos el ruido causado por el movimiento de la sangre venosa durante el movimiento. [5]\n\nCalibración específica del modelo: la SpO₂ está calibrada empíricamente en voluntarios adultos sanos con niveles normales de COHb y MetHb; no puede utilizarse un simulador funcional para evaluar la exactitud. [5]\n\nFunciones como SpHb, SpCO y SpMet son opcionales y dependen del sensor multionda rainbow y de la configuración del equipo. [5]"},"placement":{"tr":"1. Hasta boyutuna ve ölçüm bölgesine uygun, cihazla uyumlu sensörü seçin; yanlış sensör kullanımı ölçümü etkileyebilir. [5]\n2. Uygulama bölgesini değerlendirin: iyi perfüze bir bölge seçin; aynı kolda tansiyon manşonu veya arter kateteri, nem, doğum lekesi, cilt renk değişikliği, oje/akrilik tırnak ve ışık yolundaki yabancı cisimler ölçümü bozabilir. [5]\n3. Sensörü kendi kullanım talimatına göre uygulayın; yüksek ortam ışığında sensör bölgesini opak bir malzemeyle örtün. [5]\n\nGenel bağlantı bölgesi: sensör genellikle erişkinde parmak ucuna, infantlarda el veya ayağa uygulanır; LED'lerden çıkan ışık kapiller yataktan geçerek karşıdaki dedektöre ulaşır. Pletismogram ve Signal IQ ile sinyal kalitesi izlenir. [5]\n\nKesin anatomik mesafe ve 3B koordinat: Bilgi yok; sensöre özgü yerleşim için sensörün kullanım talimatına bakın. [5]","en":"1. Select a device-compatible sensor appropriate for patient size and measurement site; use of an incorrect sensor may affect measurements. [5]\n2. Assess the application site: choose a well-perfused site; a blood pressure cuff or arterial catheter on the same arm, moisture, birthmarks, skin discoloration, nail polish/acrylic nails and foreign objects in the light path may impair measurement. [5]\n3. Apply the sensor according to its own directions for use; in high ambient light, cover the sensor site with opaque material. [5]\n\nGeneral connection site: the sensor is usually applied to the fingertip in adults and to the hand or foot in infants; light from the LEDs passes through the capillary bed to the opposite detector. Signal quality is monitored with the plethysmogram and Signal IQ. [5]\n\nExact anatomical distance and 3D coordinates: no data available; refer to the sensor's directions for use for sensor-specific placement. [5]","es":"1. Seleccione un sensor compatible con el equipo y adecuado al tamaño del paciente y a la zona de medición; el uso de un sensor incorrecto puede afectar a la medición. [5]\n2. Evalúe la zona de aplicación: elija una zona bien perfundida; un manguito de presión o un catéter arterial en el mismo brazo, la humedad, las marcas de nacimiento, la alteración del color de la piel, el esmalte o las uñas acrílicas y los objetos extraños en el trayecto de la luz pueden alterar la medición. [5]\n3. Aplique el sensor según sus propias instrucciones de uso; con luz ambiental intensa, cubra la zona del sensor con material opaco. [5]\n\nZona general de conexión: el sensor suele colocarse en la yema del dedo en adultos y en la mano o el pie en lactantes; la luz de los LED atraviesa el lecho capilar hasta el detector opuesto. La calidad de la señal se vigila con el pletismograma y el Signal IQ. [5]\n\nDistancia anatómica exacta y coordenadas 3D: sin datos disponibles; consulte las instrucciones de uso del sensor para la colocación específica. [5]"},"use":{"tr":"1. Hasta boyutuna ve ölçüm bölgesine uygun sensörü seçin ve sensörün doğru bölgede olduğunu doğrulayın. [5]\n2. Cildi ve perfüzyonu değerlendirin; düşük perfüzyon mesajı sık görülüyorsa daha iyi perfüze bir bölge bulun. [5]\n3. Hasta ve bakım alanına uygun hassasiyet modunu seçin: APOD sensörün çıkma olasılığının yüksek olduğu ve hastanın sürekli gözlenmediği alanlar için, MAX düşük perfüzyonlu hastalar için önerilir; MAX, hastanın görsel olarak izlenmediği genel servisler için önerilmez. [5]\n4. Ortalama süresinin etkisini bilin: uzun ortalama süresi değerleri daha stabil yapar ancak yanıtı geciktirir ve SpO₂ ile nabız değişimlerini azaltır. [5]\n\nSayısal alarm limitleri profile ve kurum ayarına göre değişir; kullanılan cihazın IFU'suna bakın.","en":"1. Select the sensor appropriate for patient size and measurement site and verify that it is on the proper site. [5]\n2. Assess skin and perfusion; if the low perfusion message is frequently displayed, find a better-perfused site. [5]\n3. Choose the sensitivity mode appropriate for the patient and care area: APOD is recommended where there is a high probability of sensor detachment and where patients are not continuously visually monitored, MAX is recommended for patients with low perfusion; MAX is not recommended for general wards where patients are not visually monitored. [5]\n4. Understand the effect of averaging time: longer averaging makes readings more stable but delays the response and reduces measured variations in SpO₂ and pulse rate. [5]\n\nNumerical alarm limits vary with profile and institutional settings; refer to the IFU of the device in use.","es":"1. Seleccione el sensor adecuado al tamaño del paciente y a la zona de medición y compruebe que está en la zona correcta. [5]\n2. Valore la piel y la perfusión; si aparece con frecuencia el mensaje de baja perfusión, busque una zona mejor perfundida. [5]\n3. Elija el modo de sensibilidad adecuado al paciente y al área asistencial: APOD se recomienda cuando hay alta probabilidad de desprendimiento del sensor y el paciente no se vigila visualmente de forma continua, y MAX en pacientes con baja perfusión; MAX no se recomienda en salas generales sin vigilancia visual. [5]\n4. Tenga en cuenta el tiempo de promediado: un promediado más largo estabiliza las lecturas pero retrasa la respuesta y reduce las variaciones medidas de SpO₂ y pulso. [5]\n\nLos límites numéricos de alarma varían según el perfil y la configuración institucional; consulte las IFU del equipo utilizado."},"params":{"tr":"| Parametre | Birim | Aralık | Hedef / normal | Anlamı |\n|---|---|---|---|---|\n| SpO₂ (peripheral oxygen saturation) | % | 0–100 (ekran) [5] | Bilgi yok | Arteriyel hemoglobinin fonksiyonel oksijen satürasyonunun optik tahmini. [1] [5] |\n| Nabız hızı | /dk | 0–240 (ekran) [5] | Bilgi yok | Optik olarak saptanan periferik nabzın dakika başına sayısı. [1] [5] |\n| PI | % | 0,00–20 (ekran) [5] | Bilgi yok | Periferik dokudaki pulsatif kan akımının pulsatif olmayan (statik) kana oranı; periferik perfüzyonun noninvaziv ölçüsü. [1] [5] |\n| PVi | % | 0–100 (ekran) [5] | Bilgi yok | Solunum döngüsü sırasında Pi'de oluşan dinamik değişimlerin ölçüsü. [5] |\n| SpHb | g/dL | 0,0–25,0 (ekran) [5] | Bilgi yok | Total hemoglobinin noninvaziv optik tahmini. [1] [5] |\n| SpCO | % | 0–99 (ekran) [5] | Bilgi yok | Arteriyel kandaki karboksihemoglobin (carboxyhemoglobin) satürasyonunun noninvaziv tahmini. [5] |\n| SpMet | % | 0,0–99,9 (ekran) [5] | Bilgi yok | Arteriyel kandaki methemoglobin (methemoglobin) satürasyonunun noninvaziv tahmini. [5] |\n| ORi | 0–1 indeks | 0,00–1,00 [7] | Bilgi yok | Orta hiperoksik aralıkta (PaO₂ yaklaşık 100–200 mmHg) PaO₂ değişiminin birimsiz göreli göstergesi. [7] |\n\n[1] [5] [7]","en":"| Parameter | Unit | Range | Target / normal | Meaning |\n|---|---|---|---|---|\n| SpO₂ (peripheral oxygen saturation) | % | 0–100 (display) [5] | No data available | Optical estimate of the functional oxygen saturation of arterial haemoglobin. [1] [5] |\n| Pulse rate | /min | 0–240 (display) [5] | No data available | Number of optically detected peripheral pulses per minute. [1] [5] |\n| PI | % | 0.00–20 (display) [5] | No data available | Ratio of pulsatile to non-pulsatile (static) blood flow in peripheral tissue; a non-invasive measure of peripheral perfusion. [1] [5] |\n| PVi | % | 0–100 (display) [5] | No data available | Measure of the dynamic changes in Pi during the respiratory cycle. [5] |\n| SpHb | g/dL | 0.0–25.0 (display) [5] | No data available | Non-invasive optical estimate of total haemoglobin. [1] [5] |\n| SpCO | % | 0–99 (display) [5] | No data available | Non-invasive estimate of carboxyhaemoglobin saturation in arterial blood. [5] |\n| SpMet | % | 0.0–99.9 (display) [5] | No data available | Non-invasive estimate of methaemoglobin saturation in arterial blood. [5] |\n| ORi | 0–1 index | 0.00–1.00 [7] | No data available | Unitless relative indicator of PaO₂ changes in the moderate hyperoxic range (PaO₂ approximately 100–200 mmHg). [7] |\n\n[1] [5] [7]","es":"| Parámetro | Unidad | Rango | Objetivo / normal | Significado |\n|---|---|---|---|---|\n| SpO₂ (saturación periférica de oxígeno) | % | 0–100 (pantalla) [5] | Sin datos disponibles | Estimación óptica de la saturación funcional de oxígeno de la hemoglobina arterial. [1] [5] |\n| Frecuencia de pulso | /min | 0–240 (pantalla) [5] | Sin datos disponibles | Número de pulsos periféricos detectados ópticamente por minuto. [1] [5] |\n| PI (índice de perfusión) | % | 0,00–20 (pantalla) [5] | Sin datos disponibles | Cociente entre el flujo sanguíneo pulsátil y la sangre no pulsátil (estática) del tejido periférico; medida no invasiva de la perfusión periférica. [1] [5] |\n| PVi | % | 0–100 (pantalla) [5] | Sin datos disponibles | Medida de los cambios dinámicos del Pi durante el ciclo respiratorio. [5] |\n| SpHb | g/dL | 0,0–25,0 (pantalla) [5] | Sin datos disponibles | Estimación óptica no invasiva de la hemoglobina total. [1] [5] |\n| SpCO | % | 0–99 (pantalla) [5] | Sin datos disponibles | Estimación no invasiva de la saturación de carboxihemoglobina en sangre arterial. [5] |\n| SpMet | % | 0,0–99,9 (pantalla) [5] | Sin datos disponibles | Estimación no invasiva de la saturación de metahemoglobina en sangre arterial. [5] |\n| ORi | índice 0–1 | 0,00–1,00 [7] | Sin datos disponibles | Indicador relativo, sin unidades, de los cambios de PaO₂ en el rango de hiperoxia moderada (PaO₂ aproximadamente 100–200 mmHg). [7] |\n\n[1] [5] [7]"},"eval":{"tr":"**SpO₂:** Hipoksemiyi düşündüren değerler laboratuvar kan örneğiyle doğrulanmalıdır; düşük SIQ mesajında değer doğru olmayabilir. Doğruluk (ARMS), hareketsiz koşulda SpO₂ %70–100 aralığında erişkin, pediatrik ve infantlarda %2, yenidoğanlarda %3; hareket sırasında %3'tür. [5] Normal SpO₂ hipoventilasyonu dışlamaz: ek oksijen alan spontan solunumlu hastada hipoventilasyon pulse oksimetriyle güvenilir saptanamayabilir. [6] Düşük perfüzyon, aşırı hareket, cilt renk değişikliği ve dishemoglobinler ölçümü etkileyebilir; yüksek COHb veya MetHb normal görünen SpO₂ ile birlikte bulunabilir. [5]\n\n**Nabız hızı:** Radical-7, EKG tabanlı aritmi analizinin yerine kullanılmamalıdır. [5] Aritmi veya intraaortik balon gibi anormal nabız ritimleri ve hareket artefaktı pletismografi tabanlı ölçümleri etkileyebilir; doğruluk (ARMS) hareketsiz 3, hareketle 5 atım/dk'dır. [5]\n\n**PI:** Arteriyel nabız sinyal gücünü gösterir ve düşük perfüzyonda tanısal araç olarak kullanılabilir; düşük değer sensör bölgesinde düşük perfüzyon veya sensör yerleşimi sorununu düşündürür. [5] Periferik dokuya ait bir ölçüdür; organ perfüzyonunun doğrudan ölçümü değildir. [5]\n\n**PVi:** Vasküler tonus, dolaşan kan hacmi ve intratorasik basınç değişimleriyle ilgili fizyolojik değişimleri yansıtabilir; üretici kılavuzu PVi'nin yararının henüz bilinmediğini ve ek klinik çalışmalar gerektirdiğini belirtir. [5] Prob konumu, hareket, spontan solunum, akciğer kompliyansı, açık perikard, vazopressör/vazodilatör kullanımı, düşük Pi, aritmiler, kalp yetersizliği ve tidal volüm PVi'yi etkileyebilir. [5]\n\n**SpHb:** Hemoglobin ölçümlerindeki farklılık belirgin olabilir; trend verileri hastanın durumu ışığında değerlendirilmeli, klinik tabloyla uyumsuz sonuçlar tekrarlanmalı veya ek verilerle desteklenmelidir. Klinik karar öncesinde laboratuvar kan örneği analiz edilmelidir; SpHb laboratuvarın yerine geçmez. [5] Doğruluk (ARMS) 8–17 g/dL aralığında 1 g/dL'dir ve hareket veya düşük perfüzyonda doğrulanmamıştır. [5]\n\n**SpCO:** Hemoglobine bağlı karbon monoksit düzeyini yansıtır. [5] Şüpheli CO zehirlenmesinde tanı veya tedavi kararının tek dayanağı olarak kullanılmamalı, ek değerlendirme yöntemleriyle birlikte yorumlanmalıdır; MetHb yüksekliğinde SpCO beklenmedik şekilde yüksek okunabilir. [5]\n\n**SpMet:** Arteriyel kandaki methemoglobin satürasyonunu yansıtır; doğruluk (ARMS) %1–15 aralığında %1'dir. [5] Laboratuvar CO-oksimetri sonuçları farklı olabilir; karşılaştırma kan alındığı anda eş zamanlı yapılmalıdır. [5]\n\n**ORi:** Oksijenasyon bozulduğunda SpO₂ değişmeden önce azalabilir ve oksijen verilmesine (ör. preoksijenasyon) yanıtı yansıtabilir. [7] PaO₂'ye eşdeğer değildir; arter kan gazı analizinin ve klasik pulse oksimetrinin yerini tutmaz; ek oksijen alan hastalarda kullanım amaçlıdır. [7]\n\nKaynakla doğrulanmış örnek klinik senaryo: Bilgi yok.","en":"**SpO₂:** Values suggesting hypoxaemia should be confirmed with a laboratory blood sample; with a low SIQ message the value may not be accurate. Accuracy (ARMS) under no-motion conditions for SpO₂ 70–100% is 2% in adults, paediatric patients and infants and 3% in neonates; during motion it is 3%. [5] A normal SpO₂ does not exclude hypoventilation: in spontaneously breathing patients receiving supplemental oxygen, hypoventilation may not be reliably detected by pulse oximetry. [6] Low perfusion, excessive motion, skin discoloration and dyshaemoglobins may affect measurement; high COHb or MetHb may occur with a seemingly normal SpO₂. [5]\n\n**Pulse rate:** Radical-7 must not be used as a replacement for ECG-based arrhythmia analysis. [5] Abnormal pulse rhythms such as arrhythmias or an intra-aortic balloon, and motion artefact, may affect plethysmography-based measurements; accuracy (ARMS) is 3 bpm without motion and 5 bpm with motion. [5]\n\n**PI:** Indicates arterial pulse signal strength and may be used as a diagnostic tool during low perfusion; a low value suggests low perfusion at the sensor site or a sensor placement problem. [5] It is a measure of peripheral tissue; it is not a direct measure of organ perfusion. [5]\n\n**PVi:** May reflect physiological changes related to vascular tone, circulating blood volume and intrathoracic pressure excursions; the manufacturer's manual states that the utility of PVi is unknown at this time and requires further clinical studies. [5] Probe malposition, motion, spontaneous breathing, lung compliance, open pericardium, vasopressors/vasodilators, low Pi, arrhythmias, heart failure and tidal volume may affect PVi. [5]\n\n**SpHb:** Variation in haemoglobin measurements may be profound; trend data should be scrutinised in light of the patient's condition, and results inconsistent with the clinical status should be repeated or supplemented with additional data. A laboratory blood sample should be analysed before clinical decision-making; SpHb does not replace laboratory measurement. [5] Accuracy (ARMS) is 1 g/dL in the 8–17 g/dL range and has not been validated with motion or low perfusion. [5]\n\n**SpCO:** Reflects the level of carbon monoxide bound to haemoglobin. [5] In suspected carbon monoxide poisoning it must not be used as the sole basis for diagnosis or treatment decisions and must be interpreted together with additional assessment methods; elevated MetHb may cause an unexpectedly high SpCO reading. [5]\n\n**SpMet:** Reflects methaemoglobin saturation in arterial blood; accuracy (ARMS) is 1% in the 1–15% range. [5] Laboratory CO-oximetry results may differ; comparisons must be simultaneous with the blood draw. [5]\n\n**ORi:** May decrease before SpO₂ changes when oxygenation deteriorates and may reflect the response to oxygen administration (e.g. pre-oxygenation). [7] It is not equivalent to PaO₂ and cannot replace arterial blood gas analysis or conventional pulse oximetry; it is intended for patients receiving supplemental oxygen. [7]\n\nSource-verified example clinical scenario: no data available.","es":"**SpO₂:** Los valores que sugieren hipoxemia deben confirmarse con una muestra de sangre de laboratorio; con un mensaje de low SIQ el valor puede no ser exacto. La exactitud (ARMS) sin movimiento para SpO₂ del 70–100% es del 2% en adultos, pacientes pediátricos y lactantes y del 3% en neonatos; con movimiento es del 3%. [5] Una SpO₂ normal no excluye la hipoventilación: en pacientes con respiración espontánea que reciben oxígeno suplementario, la pulsioximetría puede no detectarla de forma fiable. [6] La baja perfusión, el movimiento excesivo, la alteración del color de la piel y las dishemoglobinas pueden afectar a la medición; puede haber COHb o MetHb elevadas con una SpO₂ aparentemente normal. [5]\n\n**Frecuencia de pulso:** Radical-7 no debe usarse como sustituto del análisis de arritmias basado en el ECG. [5] Los ritmos de pulso anómalos, como arritmias o balón intraaórtico, y el artefacto de movimiento pueden afectar a las mediciones basadas en la pletismografía; la exactitud (ARMS) es de 3 lpm sin movimiento y de 5 lpm con movimiento. [5]\n\n**PI:** Indica la intensidad de la señal del pulso arterial y puede utilizarse como herramienta diagnóstica en situaciones de baja perfusión; un valor bajo sugiere baja perfusión en la zona del sensor o un problema de colocación. [5] Es una medida del tejido periférico; no mide directamente la perfusión de los órganos. [5]\n\n**PVi:** Puede reflejar cambios fisiológicos relacionados con el tono vascular, el volumen sanguíneo circulante y las variaciones de la presión intratorácica; el manual del fabricante indica que la utilidad del PVi se desconoce actualmente y requiere más estudios clínicos. [5] La mala posición de la sonda, el movimiento, la respiración espontánea, la distensibilidad pulmonar, el pericardio abierto, los vasopresores/vasodilatadores, un Pi bajo, las arritmias, la insuficiencia cardiaca y el volumen corriente pueden afectar al PVi. [5]\n\n**SpHb:** La variación de las mediciones de hemoglobina puede ser importante; los datos de tendencia deben valorarse según el estado del paciente, y los resultados incoherentes con la situación clínica deben repetirse o completarse con datos adicionales. Antes de tomar decisiones clínicas debe analizarse una muestra de sangre en el laboratorio; la SpHb no sustituye a la medición de laboratorio. [5] La exactitud (ARMS) es de 1 g/dL en el rango de 8–17 g/dL y no se ha validado con movimiento ni con baja perfusión. [5]\n\n**SpCO:** Refleja el nivel de monóxido de carbono unido a la hemoglobina. [5] Ante sospecha de intoxicación por monóxido de carbono no debe ser la única base para decisiones diagnósticas o terapéuticas y debe interpretarse junto con otros métodos de evaluación; una MetHb elevada puede producir una lectura de SpCO inesperadamente alta. [5]\n\n**SpMet:** Refleja la saturación de metahemoglobina en sangre arterial; la exactitud (ARMS) es del 1% en el rango del 1–15%. [5] Los resultados de cooximetría de laboratorio pueden diferir; las comparaciones deben ser simultáneas a la extracción de sangre. [5]\n\n**ORi:** Puede disminuir antes de que cambie la SpO₂ cuando se deteriora la oxigenación y puede reflejar la respuesta a la administración de oxígeno (p. ej., preoxigenación). [7] No equivale a la PaO₂ y no sustituye a la gasometría arterial ni a la pulsioximetría convencional; está destinado a pacientes que reciben oxígeno suplementario. [7]\n\nEscenario clínico de ejemplo verificado con fuentes: sin datos disponibles."},"trouble":{"tr":"- Hareket: aşırı hareket SpO₂ ölçümünü bozabilir; aşırı harekette SpCO, SpMet ve SpHb tire (---) ve düşük SIQ mesajıyla gösterilir. [5]\n- Düşük perfüzyon: çok düşük perfüzyon ölçüm yokluğuna veya yanlış ölçüme yol açabilir; düşük perfüzyon mesajı sık görülürse daha iyi perfüze bölge bulunur, MAX hassasiyet modu düşünülebilir. [5]\n- Dış ışık: ameliyat lambaları (özellikle ksenon), bilirubin lambaları, floresan ışık, kızılötesi ısıtıcılar ve doğrudan güneş ışığı ölçümü bozabilir; sensör bölgesi opak malzemeyle örtülür. [5]\n- Tırnak ürünleri/sensör uyumsuzluğu: oje, akrilik tırnak, sim ve yanlış sensör kullanımı ölçümü etkileyebilir; hasta boyutuna uygun sensör ve doğru bölge doğrulanır. [5]\n- Normal SpO₂ yeterli ventilasyon garantisi değildir: ek oksijen hipoventilasyonun pulse oksimetriyle saptanmasını bozabilir; Radical-7 apne monitörü olarak kullanılmamalıdır. [5] [6]\n- Sensör bölgesi: sensör kendi kullanım talimatına göre uygulanır ve kontrol edilir; yanlış uygulanmış veya kısmen yerinden çıkmış sensör ölçüm yokluğuna ya da yanlış ölçüme yol açabilir. Test koşullarında sensör-cilt arayüz sıcaklığı 41 °C'nin altında bulunmuştur. [5]\n- Dishemoglobinler ve cilt rengi: dishemoglobinler oksijen taşıyamaz ancak geleneksel pulse oksimetride oksijenlenmiş hemoglobin olarak algılanır; yüksek COHb/MetHb, cilt renk değişikliği ve yüksek bilirubin ölçümü etkileyebilir. Doğruluk çalışmaları açık ve koyu cilt pigmentasyonlu gönüllüleri içermiştir. [5]","en":"- Motion: excessive motion may impair SpO₂ measurement; during excessive motion SpCO, SpMet and SpHb are displayed as dashes (---) with a low SIQ message. [5]\n- Low perfusion: very low perfusion may result in no or incorrect readings; if the low perfusion message is frequently displayed, find a better-perfused site and consider MAX sensitivity mode. [5]\n- Ambient light: surgical lights (especially xenon), bilirubin lamps, fluorescent lights, infrared heating lamps and direct sunlight may impair measurement; cover the sensor site with opaque material. [5]\n- Nail products/sensor mismatch: nail polish, acrylic nails, glitter and use of an incorrect sensor may affect measurement; verify the proper sensor for patient size and the proper site. [5]\n- A normal SpO₂ does not guarantee adequate ventilation: supplemental oxygen may impair detection of hypoventilation by pulse oximetry; Radical-7 must not be used as an apnoea monitor. [5] [6]\n- Sensor site: the sensor is applied and checked according to its own directions for use; a misapplied or partially dislodged sensor may cause no or incorrect readings. Under test conditions the skin-sensor interface temperature was below 41 °C. [5]\n- Dyshaemoglobins and skin colour: dyshaemoglobins cannot transport oxygen but are recognised as oxygenated haemoglobin by conventional pulse oximetry; high COHb/MetHb, skin discoloration and elevated bilirubin may affect measurement. Accuracy studies included volunteers with light to dark skin pigmentation. [5]","es":"- Movimiento: el movimiento excesivo puede alterar la medición de SpO₂; con movimiento excesivo, SpCO, SpMet y SpHb se muestran como guiones (---) con un mensaje de low SIQ. [5]\n- Baja perfusión: una perfusión muy baja puede producir ausencia de lecturas o lecturas incorrectas; si el mensaje de baja perfusión aparece con frecuencia, busque una zona mejor perfundida y considere el modo de sensibilidad MAX. [5]\n- Luz ambiental: las lámparas quirúrgicas (sobre todo de xenón), las lámparas de bilirrubina, la luz fluorescente, las lámparas de calor infrarrojo y la luz solar directa pueden alterar la medición; cubra la zona del sensor con material opaco. [5]\n- Productos de uñas/sensor inadecuado: el esmalte, las uñas acrílicas, la purpurina y el uso de un sensor incorrecto pueden afectar a la medición; compruebe que el sensor es adecuado al tamaño del paciente y que la zona es correcta. [5]\n- Una SpO₂ normal no garantiza una ventilación adecuada: el oxígeno suplementario puede dificultar la detección de hipoventilación por pulsioximetría; Radical-7 no debe utilizarse como monitor de apnea. [5] [6]\n- Zona del sensor: el sensor se aplica y se revisa según sus propias instrucciones de uso; un sensor mal colocado o parcialmente desprendido puede producir ausencia de lecturas o lecturas incorrectas. En condiciones de prueba, la temperatura de la interfaz piel-sensor fue inferior a 41 °C. [5]\n- Dishemoglobinas y color de la piel: las dishemoglobinas no transportan oxígeno, pero la pulsioximetría convencional las reconoce como hemoglobina oxigenada; la COHb/MetHb elevada, la alteración del color de la piel y la bilirrubina elevada pueden afectar a la medición. Los estudios de exactitud incluyeron voluntarios con pigmentación cutánea clara a oscura. [5]"},"special":{"tr":"- SpO₂ ve nabız: erişkin, pediatrik ve yenidoğan hastalarda, hareketli ve hareketsiz koşullarda endikedir. [5]\n- SpCO: erişkin, pediatrik ve infant hastalarda hareketsiz koşulda; SpMet: erişkin, pediatrik ve yenidoğan hastalarda hareketsiz koşulda; SpHb: yalnızca erişkin ve pediatrik hastalarda hareketsiz koşulda endikedir. [5]\n- Yenidoğanlarda SpO₂ doğruluğu (ARMS) hareketsiz koşulda %3'tür. [5]\n- Fetal hemoglobin, pH, sıcaklık, pCO₂ ve 2,3-DPG, arter kan gazındaki SaO₂ ile SpO₂ karşılaştırmasını etkileyebilir. [5]\n- ORi: ek oksijen alan hastalarda kullanım amaçlıdır; ORi bu ABD kullanım kılavuzunun parametre listesinde yer almaz, kullanılabilirliği ülkeye ve cihaz yapılandırmasına göre doğrulanmalıdır. [5] [7]","en":"- SpO₂ and pulse rate: indicated for adult, paediatric and neonatal patients under motion and no-motion conditions. [5]\n- SpCO: adult, paediatric and infant patients under no-motion conditions; SpMet: adult, paediatric and neonatal patients under no-motion conditions; SpHb: adult and paediatric patients only, under no-motion conditions. [5]\n- In neonates, SpO₂ accuracy (ARMS) under no-motion conditions is 3%. [5]\n- Fetal haemoglobin, pH, temperature, pCO₂ and 2,3-DPG may affect the comparison of SpO₂ with SaO₂ from arterial blood gas analysis. [5]\n- ORi: intended for patients receiving supplemental oxygen; ORi is not included in the parameter list of this US operator's manual, and its availability must be verified by country and device configuration. [5] [7]","es":"- SpO₂ y frecuencia de pulso: indicadas en pacientes adultos, pediátricos y neonatales, con y sin movimiento. [5]\n- SpCO: adultos, pacientes pediátricos y lactantes sin movimiento; SpMet: adultos, pacientes pediátricos y neonatos sin movimiento; SpHb: solo adultos y pacientes pediátricos, sin movimiento. [5]\n- En neonatos, la exactitud (ARMS) de la SpO₂ sin movimiento es del 3%. [5]\n- La hemoglobina fetal, el pH, la temperatura, la pCO₂ y el 2,3-DPG pueden afectar a la comparación de la SpO₂ con la SaO₂ de la gasometría arterial. [5]\n- ORi: destinado a pacientes que reciben oxígeno suplementario; el ORi no figura en la lista de parámetros de este manual del operador estadounidense y su disponibilidad debe verificarse según el país y la configuración del equipo. [5] [7]"},"roles":{"tr":"Aşağıdaki başlıklar, her meslek grubu için önerilen öğrenme konularını gösterir; mevzuatta tanımlanan mesleki yetki ve sorumlulukları belirlemez.\n\n- **Teknisyen:** Eğitim odağı: uyumlu sarf malzemelerinin ve bağlantıların hazırlanması, kontrol listesinin kullanılması ve yeniden kullanıma hazırlama işlemleri. Yeniden kullanılabilir parçaların temizliği, dezenfeksiyon veya sterilizasyon öncesinde yapılır; kullanılacak kimyasal madde ve yöntem, malzemenin özelliklerine ve üreticinin talimatlarına göre seçilir. [4]\n- **Asistan:** Eğitim odağı: parametrenin tanımı, sinyal kalitesi, sık yapılan yorum hataları ve sorumlu uzmanla olgu değerlendirmesi.\n- **Uzman:** Eğitim odağı: klinik bağlam, yöntemin sınırlamaları ve kanıtın uygulamaya aktarılması.\n\n[4]","en":"The following sections suggest learning objectives for each professional group; they do not define professional responsibilities or scope of practice under applicable regulations.\n\n- **Technician:** Training focus: preparation of compatible consumables and connections, checklist and reprocessing. Reusable parts are cleaned before disinfection or sterilisation; the chemical agent and method are chosen according to the material and the manufacturer's instructions. [4]\n- **Resident:** Training focus: parameter definitions, signal quality, common interpretation errors and case review with the responsible specialist.\n- **Specialist:** Training focus: clinical context, limitations of the method and translation of evidence into practice.\n\n[4]","es":"Los siguientes apartados proponen objetivos de aprendizaje para cada grupo profesional; no definen las competencias ni las responsabilidades establecidas por la normativa.\n\n- **Técnico:** Enfoque formativo: preparación de consumibles y conexiones compatibles, lista de verificación y reprocesamiento. Las piezas reutilizables se limpian antes de la desinfección o esterilización; el agente químico y el método se eligen según el material y las instrucciones del fabricante. [4]\n- **Residente:** Enfoque formativo: definición de los parámetros, calidad de la señal, errores frecuentes de interpretación y revisión de casos con el especialista responsable.\n- **Especialista:** Enfoque formativo: contexto clínico, limitaciones del método y aplicación de la evidencia a la práctica.\n\n[4]"}},"params":[{"label":{"tr":"SpO₂","en":"SpO₂","es":"SpO₂"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Arteriyel hemoglobinin fonksiyonel oksijen satürasyonunun optik tahmini.","en":"Optical estimate of the functional oxygen saturation of arterial haemoglobin.","es":"Estimación óptica de la saturación funcional de oxígeno de la hemoglobina arterial."},"interpretation":{"tr":"Hipoksemiyi düşündüren değerler laboratuvar kan örneğiyle doğrulanmalıdır; düşük SIQ mesajında değer doğru olmayabilir. [5]","en":"Values suggesting hypoxaemia should be confirmed with a laboratory blood sample; with a low SIQ message the value may not be accurate. [5]","es":"Los valores que sugieren hipoxemia deben confirmarse con una muestra de sangre de laboratorio; con un mensaje de low SIQ el valor puede no ser exacto. [5]"},"context":{"tr":"Normal SpO₂ hipoventilasyonu dışlamaz (özellikle ek oksijenle); düşük perfüzyon, hareket, cilt renk değişikliği ve dishemoglobinler ölçümü etkileyebilir. [5] [6]","en":"A normal SpO₂ does not exclude hypoventilation (especially with supplemental oxygen); low perfusion, motion, skin discoloration and dyshaemoglobins may affect measurement. [5] [6]","es":"Una SpO₂ normal no excluye la hipoventilación (sobre todo con oxígeno suplementario); la baja perfusión, el movimiento, la alteración del color de la piel y las dishemoglobinas pueden afectar a la medición. [5] [6]"},"range":{"tr":"Ekran aralığı %0–100; doğruluk (ARMS) %70–100 aralığında hareketsiz %2 (yenidoğan %3), hareketle %3. [5]","en":"Display range 0–100%; accuracy (ARMS) for 70–100%: 2% without motion (neonates 3%), 3% with motion. [5]","es":"Rango de visualización 0–100%; exactitud (ARMS) para 70–100%: 2% sin movimiento (neonatos 3%), 3% con movimiento. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"Nabız hızı","en":"Pulse rate","es":"Frecuencia de pulso"},"unit":{"tr":"/dk","en":"/min","es":"/min"},"meaning":{"tr":"Optik olarak saptanan periferik nabzın dakika başına sayısı.","en":"Number of optically detected peripheral pulses per minute.","es":"Número de pulsos periféricos detectados ópticamente por minuto."},"interpretation":{"tr":"EKG tabanlı aritmi analizinin yerine geçmez; EKG kalp hızıyla birlikte değerlendirilir. [5]","en":"Does not replace ECG-based arrhythmia analysis; it is interpreted together with the ECG heart rate. [5]","es":"No sustituye al análisis de arritmias basado en el ECG; se interpreta junto con la frecuencia cardiaca del ECG. [5]"},"context":{"tr":"Aritmi veya intraaortik balon gibi anormal nabız ritimleri ve hareket artefaktı ölçümü etkileyebilir. [5]","en":"Abnormal pulse rhythms such as arrhythmias or an intra-aortic balloon, and motion artefact, may affect measurement. [5]","es":"Los ritmos de pulso anómalos, como arritmias o balón intraaórtico, y el artefacto de movimiento pueden afectar a la medición. [5]"},"range":{"tr":"Ekran aralığı 0–240/dk; doğruluk (ARMS) 25–240/dk aralığında hareketsiz 3, hareketle 5/dk. [5]","en":"Display range 0–240/min; accuracy (ARMS) for 25–240/min: 3/min without motion, 5/min with motion. [5]","es":"Rango de visualización 0–240/min; exactitud (ARMS) para 25–240/min: 3/min sin movimiento, 5/min con movimiento. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"PI","en":"PI","es":"PI (índice de perfusión)"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Periferik dokudaki pulsatif kan akımının pulsatif olmayan (statik) kana oranı; periferik perfüzyonun noninvaziv ölçüsü.","en":"Ratio of pulsatile to non-pulsatile (static) blood flow in peripheral tissue; a non-invasive measure of peripheral perfusion.","es":"Cociente entre el flujo sanguíneo pulsátil y la sangre no pulsátil (estática) del tejido periférico; medida no invasiva de la perfusión periférica."},"interpretation":{"tr":"Arteriyel nabız sinyal gücünü gösterir; düşük değer sensör bölgesinde düşük perfüzyon veya sensör yerleşimi sorununu düşündürür. [5]","en":"Indicates arterial pulse signal strength; a low value suggests low perfusion at the sensor site or a sensor placement problem. [5]","es":"Indica la intensidad de la señal del pulso arterial; un valor bajo sugiere baja perfusión en la zona del sensor o un problema de colocación. [5]"},"context":{"tr":"Periferik dokuya ait bir ölçüdür; organ perfüzyonunun doğrudan ölçümü değildir. [5]","en":"A measure of peripheral tissue; not a direct measure of organ perfusion. [5]","es":"Es una medida del tejido periférico; no mide directamente la perfusión de los órganos. [5]"},"range":{"tr":"Ekran aralığı 0,00–20. [5]","en":"Display range 0.00–20. [5]","es":"Rango de visualización 0,00–20. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"PVi","en":"PVi","es":"PVi"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Solunum döngüsü sırasında Pi'de oluşan dinamik değişimlerin ölçüsü. [5]","en":"Measure of the dynamic changes in Pi during the respiratory cycle. [5]","es":"Medida de los cambios dinámicos del Pi durante el ciclo respiratorio. [5]"},"interpretation":{"tr":"Vasküler tonus, dolaşan kan hacmi ve intratorasik basınç değişimlerini yansıtabilir; üretici kılavuzuna göre PVi'nin yararı henüz bilinmemektedir ve ek klinik çalışma gerektirir. [5]","en":"May reflect vascular tone, circulating blood volume and intrathoracic pressure excursions; according to the manufacturer's manual, the utility of PVi is unknown at this time and requires further clinical studies. [5]","es":"Puede reflejar el tono vascular, el volumen sanguíneo circulante y las variaciones de la presión intratorácica; según el manual del fabricante, la utilidad del PVi se desconoce actualmente y requiere más estudios clínicos. [5]"},"context":{"tr":"Spontan solunum, aritmi, vazopressör/vazodilatör, düşük Pi, açık perikard, akciğer kompliyansı, tidal volüm, prob konumu ve hareket PVi'yi etkileyebilir. [5]","en":"Spontaneous breathing, arrhythmia, vasopressors/vasodilators, low Pi, open pericardium, lung compliance, tidal volume, probe position and motion may affect PVi. [5]","es":"La respiración espontánea, las arritmias, los vasopresores/vasodilatadores, un Pi bajo, el pericardio abierto, la distensibilidad pulmonar, el volumen corriente, la posición de la sonda y el movimiento pueden afectar al PVi. [5]"},"range":{"tr":"Ekran aralığı %0–100. [5]","en":"Display range 0–100%. [5]","es":"Rango de visualización 0–100%. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"SpHb","en":"SpHb","es":"SpHb"},"unit":{"tr":"g/dL","en":"g/dL","es":"g/dL"},"meaning":{"tr":"Total hemoglobinin noninvaziv optik tahmini.","en":"Non-invasive optical estimate of total haemoglobin.","es":"Estimación óptica no invasiva de la hemoglobina total."},"interpretation":{"tr":"Trend verileri hastanın durumu ışığında değerlendirilir; klinik tabloyla uyumsuz sonuçlar tekrarlanır veya ek verilerle desteklenir. [5]","en":"Trend data are scrutinised in light of the patient's condition; results inconsistent with the clinical status are repeated or supplemented with additional data. [5]","es":"Los datos de tendencia se valoran según el estado del paciente; los resultados incoherentes con la situación clínica se repiten o se completan con datos adicionales. [5]"},"context":{"tr":"Klinik karar öncesinde laboratuvar kan örneği analiz edilmelidir; tek başına laboratuvarın yerine geçmez. [5]","en":"A laboratory blood sample should be analysed before clinical decision-making; it does not replace laboratory measurement on its own. [5]","es":"Antes de tomar decisiones clínicas debe analizarse una muestra de sangre en el laboratorio; por sí sola no sustituye a la medición de laboratorio. [5]"},"range":{"tr":"Ekran aralığı 0,0–25,0 g/dL; doğruluk (ARMS) 8–17 g/dL aralığında 1 g/dL (hareket ve düşük perfüzyonda doğrulanmamış). [5]","en":"Display range 0.0–25.0 g/dL; accuracy (ARMS) 1 g/dL in the 8–17 g/dL range (not validated with motion or low perfusion). [5]","es":"Rango de visualización 0,0–25,0 g/dL; exactitud (ARMS) de 1 g/dL en el rango de 8–17 g/dL (no validada con movimiento ni baja perfusión). [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"SpCO","en":"SpCO","es":"SpCO"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Arteriyel kandaki karboksihemoglobin satürasyonunun noninvaziv tahmini. [5]","en":"Non-invasive estimate of carboxyhaemoglobin saturation in arterial blood. [5]","es":"Estimación no invasiva de la saturación de carboxihemoglobina en sangre arterial. [5]"},"interpretation":{"tr":"Hemoglobine bağlı karbon monoksit düzeyini yansıtır; MetHb yüksekliğinde beklenmedik şekilde yüksek okunabilir. [5]","en":"Reflects the level of carbon monoxide bound to haemoglobin; may read unexpectedly high when MetHb is elevated. [5]","es":"Refleja el nivel de monóxido de carbono unido a la hemoglobina; puede ser inesperadamente alta si la MetHb está elevada. [5]"},"context":{"tr":"Şüpheli CO zehirlenmesinde tanı veya tedavi kararının tek dayanağı değildir; ek değerlendirme yöntemleriyle birlikte yorumlanır. [5]","en":"In suspected carbon monoxide poisoning it is not the sole basis for diagnosis or treatment decisions; it is interpreted together with additional assessment methods. [5]","es":"Ante sospecha de intoxicación por monóxido de carbono no es la única base para decisiones diagnósticas o terapéuticas; se interpreta junto con otros métodos de evaluación. [5]"},"range":{"tr":"Ekran aralığı %0–99; doğruluk (ARMS) %1–40 aralığında %3. [5]","en":"Display range 0–99%; accuracy (ARMS) 3% in the 1–40% range. [5]","es":"Rango de visualización 0–99%; exactitud (ARMS) del 3% en el rango del 1–40%. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"SpMet","en":"SpMet","es":"SpMet"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Arteriyel kandaki methemoglobin satürasyonunun noninvaziv tahmini. [5]","en":"Non-invasive estimate of methaemoglobin saturation in arterial blood. [5]","es":"Estimación no invasiva de la saturación de metahemoglobina en sangre arterial. [5]"},"interpretation":{"tr":"Methemoglobin düzeyini yansıtır; yüksek MetHb normal görünen SpO₂ ile birlikte bulunabilir. [5]","en":"Reflects the methaemoglobin level; high MetHb may occur with a seemingly normal SpO₂. [5]","es":"Refleja el nivel de metahemoglobina; puede haber MetHb elevada con una SpO₂ aparentemente normal. [5]"},"context":{"tr":"Laboratuvar CO-oksimetri sonuçları farklı olabilir; karşılaştırma kan alındığı anda eş zamanlı yapılmalıdır. [5]","en":"Laboratory CO-oximetry results may differ; comparisons must be simultaneous with the blood draw. [5]","es":"Los resultados de cooximetría de laboratorio pueden diferir; las comparaciones deben ser simultáneas a la extracción de sangre. [5]"},"range":{"tr":"Ekran aralığı %0,0–99,9; doğruluk (ARMS) %1–15 aralığında %1. [5]","en":"Display range 0.0–99.9%; accuracy (ARMS) 1% in the 1–15% range. [5]","es":"Rango de visualización 0,0–99,9%; exactitud (ARMS) del 1% en el rango del 1–15%. [5]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"display_range_source_supported"}},{"label":{"tr":"ORi","en":"ORi","es":"ORi"},"unit":{"tr":"0–1 indeks","en":"0–1 index","es":"índice 0–1"},"meaning":{"tr":"Orta hiperoksik aralıkta (PaO₂ yaklaşık 100–200 mmHg) PaO₂ değişiminin birimsiz göreli göstergesi. [7]","en":"Unitless relative indicator of PaO₂ changes in the moderate hyperoxic range (PaO₂ approximately 100–200 mmHg). [7]","es":"Indicador relativo, sin unidades, de los cambios de PaO₂ en el rango de hiperoxia moderada (PaO₂ aproximadamente 100–200 mmHg). [7]"},"interpretation":{"tr":"Oksijenasyon bozulduğunda SpO₂ değişmeden önce azalabilir. [7]","en":"May decrease before SpO₂ changes when oxygenation deteriorates. [7]","es":"Puede disminuir antes de que cambie la SpO₂ cuando se deteriora la oxigenación. [7]"},"context":{"tr":"PaO₂'ye eşdeğer değildir, arter kan gazının yerini tutmaz; ek oksijen alan hastalarda kullanım amaçlıdır. [7]","en":"Not equivalent to PaO₂ and does not replace arterial blood gas analysis; intended for patients receiving supplemental oxygen. [7]","es":"No equivale a la PaO₂ ni sustituye a la gasometría arterial; destinado a pacientes que reciben oxígeno suplementario. [7]"},"range":{"tr":"0,00–1,00 (birimsiz). [7]","en":"0.00–1.00 (unitless). [7]","es":"0,00–1,00 (sin unidades). [7]"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}}],"references":[{"n":1,"title":"Rad-67® Pulse CO-Oximeter® Spot-Check Operator's Manual","publisher":"Masimo","year":2021,"url":"https://techdocs.masimo.com/globalassets/techdocs/pdf/lab-10262d_master.pdf","doi":null,"type":"ifu"},{"n":2,"title":"Masimo Radical-7","publisher":"Masimo","year":null,"url":"https://www.masimo.com/products/bedside-solutions/radical-7/","doi":null,"type":"manufacturer"},{"n":3,"title":"Masimo rainbow parametreleri","publisher":"Masimo","year":null,"url":"https://www.masimo.com/technology/pulse-co-oximetry/rainbow/","doi":null,"type":"manufacturer"},{"n":4,"title":"Guideline for Disinfection and Sterilization: Summary Recommendations","publisher":"CDC","year":"2008; web özeti 2023","url":"https://www.cdc.gov/infection-control/hcp/disinfection-sterilization/summary-recommendations.html","doi":null,"type":"guideline"},{"n":5,"title":"Radical-7 Pulse CO-Oximeter Operator's Manual (LAB-5475L)","publisher":"Masimo","year":2021,"url":"https://techdocs.masimo.com/globalassets/techdocs/pdf/lab-5475l_master.pdf","doi":null,"type":"ifu"},{"n":6,"title":"Supplemental oxygen impairs detection of hypoventilation by pulse oximetry","publisher":"Chest 2004;126(5):1552-1558 (Fu ES et al.)","year":2004,"url":"https://pubmed.ncbi.nlm.nih.gov/15539726/","doi":"10.1378/chest.126.5.1552","type":"article"},{"n":7,"title":"Scheeren TWL, Belda FJ, Perel A. The oxygen reserve index (ORI): a new tool to monitor oxygen therapy. J Clin Monit Comput 2018;32:379-89","publisher":"J Clin Monit Comput","year":2018,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5943373/","doi":"10.1007/s10877-017-0049-4","type":"article"}],"images":[{"src":"content/img/radical-7-urun.jpg","kind":"photo","alt":{"tr":"Radical-7 — üretici görseli","en":"Radical-7 — manufacturer image","es":"Radical-7 — imagen del fabricante"},"caption":{"tr":"Üretici görseli; model ve yapılandırma ülkeye göre değişebilir.","en":"Manufacturer image; model and configuration may vary by country.","es":"Imagen del fabricante; el modelo y la configuración pueden variar según el país."},"credit":"Masimo","sourceUrl":"https://www.masimo.com/products/bedside-solutions/radical-7/","rights":"publication_permission_declared_by_site_owner","rightsDate":"2026-10-07"},{"src":"content/img/radical-7-sema.svg","kind":"schematic","alt":{"tr":"Radical-7 için temsili bağlantı bölgesi","en":"Representative connection area for Radical-7","es":"Zona de conexión representativa de Radical-7"},"caption":{"tr":"Genel uygulama şemasıdır; sensörün kesin anatomik yerleşimini göstermez.","en":"General application diagram; it does not show the exact anatomical position of the sensor.","es":"Esquema general de aplicación; no muestra la posición anatómica exacta del sensor."}}],"external":[],"photoWithheld":false};
